"use strict";
import { useCallback, useEffect, useMemo, useRef } from "react";
import { useVeABXLock, useVeABXUserLocks } from "hooks/useVeABXLocks";
import { useLockDepositStatus } from "hooks/useManagedDeposits";
import LockTimeAndVotingPower from "pages/Locks/common/LockTimeAndVotingPower";
import { Flex, SpinningLoader, StarBorderButton, Text, useSporeColors } from "ui/src";
import { popupRegistry } from "components/Popups/registry";
import { PopupType } from "components/Popups/types";
import {
  MAX_LOCK_DURATION_SECONDS,
  calculateVotingPowerFromDays,
  formatABXAmount,
  secondsToDays
} from "utils/lockCalculations";
import { safeBigInt } from "utils/safeBigInt";
import { formatUnits } from "viem";
import { useAccount } from "wagmi";
import { errorToString } from "utilities/src/errors";
import { useModifyLockContext } from "../ModifyLockContextProvider";
import ChangeLockAndOptionButton from "./ChangeLockAndOptionButton";
import Extend from "./Extend";
import Increase from "./Increase";
import Merge from "./Merge";
import StatusCards from "./StatusCards";
import ToggleOptions from "./ToggleOptions";
import Transfer from "./Transfer";
import ResetVote from "./ResetVote";
import { useVeABXRebaseClaimables } from "hooks/useVeABXRebaseClaimables";
import { useClaimRebaseReward } from "hooks/useClaimRebaseReward";
export default function LockModifyOptions() {
  const { address: account } = useAccount();
  const { activeOption, selectedLockId, formData } = useModifyLockContext();
  const { data: currentLock } = useVeABXLock(selectedLockId || void 0);
  const { data: userLocks } = useVeABXUserLocks(account);
  const colors = useSporeColors();
  const { isDeposited: isRelayDeposited, managedTokenId } = useLockDepositStatus(currentLock);
  const userLockIds = useMemo(() => (userLocks ?? []).map((lock) => lock.id), [userLocks]);
  const {
    claimableMap: rebaseClaimableMap,
    isLoading: rebaseLoading,
    isFetching: rebaseFetching,
    refetch: refetchRebaseClaimables
  } = useVeABXRebaseClaimables(userLockIds);
  if (currentLock && isRelayDeposited) {
    return <Flex mt={"$spacing24"} flexDirection="column" gap={"$gap24"}>
        <StatusCards />
        <Flex
      p={"$spacing16"}
      borderRadius={"$rounded12"}
      borderWidth={1}
      borderColor={"$surface3"}
      backgroundColor={"$surface2"}
    >
          <Flex gap={"$gap12"}>
            <Text variant="subheading1">ABX Vault Managed Lock</Text>
            <Text variant="body3" color="$neutral2">
              Lock #{currentLock.id} is currently deposited into ABX Vault #{managedTokenId}. Withdraw it from the ABX Vault to
              enable lock modifications.
            </Text>
          </Flex>
        </Flex>
      </Flex>;
  }
  const getUpdatedValues = () => {
    if (!currentLock) return { lockTime: 0, votingPower: "0" };
    const currentUnlockTime = parseInt(currentLock.lockEnd);
    const currentTimeSeconds = Math.floor(Date.now() / 1e3);
    const remainingDays = Math.max(0, secondsToDays(currentUnlockTime - currentTimeSeconds));
    switch (activeOption) {
      case "Increase": {
        if (!formData.increaseAmount) {
          return {
            lockTime: currentLock.permanent ? 0 : remainingDays,
            votingPower: BigInt(currentLock.votingPower)
          };
        }
        try {
          const currentAmount = formatUnits(BigInt(currentLock.amount), 18);
          const newTotalAmount = parseFloat(currentAmount) + parseFloat(formData.increaseAmount);
          if (currentLock.permanent) {
            return {
              lockTime: 0,
              // Permanent lock has no expiry
              votingPower: newTotalAmount.toString()
              // 1:1 ratio for permanent locks
            };
          }
          const newVotingPower = calculateVotingPowerFromDays(newTotalAmount.toString(), remainingDays);
          return {
            lockTime: remainingDays,
            votingPower: newVotingPower
          };
        } catch (error) {
          console.error("Error calculating increase values:", error);
          return {
            lockTime: currentLock.permanent ? 0 : remainingDays,
            votingPower: BigInt(currentLock.votingPower)
          };
        }
      }
      case "Extend": {
        try {
          const currentAmount = formatUnits(BigInt(currentLock.amount), 18);
          if (currentLock.permanent) {
            if (formData.unlockPermanent) {
              const unlockDays = secondsToDays(MAX_LOCK_DURATION_SECONDS);
              const newVotingPower = calculateVotingPowerFromDays(currentAmount, unlockDays);
              return {
                lockTime: unlockDays,
                votingPower: newVotingPower
              };
            }
            return {
              lockTime: 0,
              votingPower: BigInt(currentLock.votingPower)
            };
          }
          if (formData.extendToMaxLock) {
            return {
              lockTime: 0,
              // Permanent lock has no expiry
              votingPower: currentAmount
              // 1:1 ratio for permanent locks
            };
          } else if (formData.extendDays > 0) {
            const newTotalDays = remainingDays + formData.extendDays;
            const newVotingPower = calculateVotingPowerFromDays(currentAmount, newTotalDays);
            return {
              lockTime: newTotalDays,
              votingPower: newVotingPower
            };
          }
          return {
            lockTime: currentLock.permanent ? 0 : remainingDays,
            votingPower: BigInt(currentLock.votingPower)
          };
        } catch (error) {
          console.error("Error calculating extend values:", error);
          return {
            lockTime: currentLock.permanent ? 0 : remainingDays,
            votingPower: BigInt(currentLock.votingPower)
          };
        }
      }
      case "Merge": {
        if (!formData.selectedMergeLockId) {
          return {
            lockTime: currentLock.permanent ? 0 : remainingDays,
            votingPower: BigInt(currentLock.votingPower)
          };
        }
        try {
          if (!userLocks) {
            return {
              lockTime: currentLock.permanent ? 0 : remainingDays,
              votingPower: BigInt(currentLock.votingPower)
            };
          }
          const selectedLock = userLocks.find((lock) => lock.id === formData.selectedMergeLockId);
          if (!selectedLock) {
            return {
              lockTime: currentLock.permanent ? 0 : remainingDays,
              votingPower: BigInt(currentLock.votingPower)
            };
          }
          const combinedAmount = BigInt(currentLock.amount) + BigInt(selectedLock.amount);
          const combinedAmountFormatted = formatUnits(combinedAmount, 18);
          let newLockTime;
          let isPermanent = false;
          if (currentLock.permanent || selectedLock.permanent) {
            isPermanent = true;
            newLockTime = 0;
          } else {
            const currentLockEnd = parseInt(currentLock.lockEnd);
            const selectedLockEnd = parseInt(selectedLock.lockEnd);
            const maxLockEnd = Math.max(currentLockEnd, selectedLockEnd);
            const remainingSeconds = Math.max(0, maxLockEnd - currentTimeSeconds);
            newLockTime = secondsToDays(remainingSeconds);
          }
          let newVotingPower;
          if (isPermanent) {
            const currentVotingPowerWei = BigInt(currentLock.votingPower);
            const selectedVotingPowerWei = BigInt(selectedLock.votingPower);
            const combinedVotingPowerWei = currentVotingPowerWei + selectedVotingPowerWei;
            newVotingPower = formatUnits(combinedVotingPowerWei, 18);
          } else {
            newVotingPower = calculateVotingPowerFromDays(combinedAmountFormatted, newLockTime);
          }
          return {
            lockTime: newLockTime,
            votingPower: newVotingPower
          };
        } catch (error) {
          console.error("Error calculating merge values:", error);
          return {
            lockTime: currentLock.permanent ? 0 : remainingDays,
            votingPower: BigInt(currentLock.votingPower)
          };
        }
      }
      default:
        return {
          lockTime: currentLock.permanent ? 0 : remainingDays,
          votingPower: BigInt(currentLock.votingPower)
        };
    }
  };
  const { lockTime, votingPower } = getUpdatedValues();
  const rebaseClaimable = currentLock ? rebaseClaimableMap.get(currentLock.id) ?? 0n : 0n;
  const isRebaseLoading = rebaseLoading || rebaseFetching;
  const hasClaimableRebase = rebaseClaimable > 0n;
  const rebaseDisplay = isRebaseLoading ? "Loading\u2026" : `${formatABXAmount(rebaseClaimable)} ABX`;
  const pendingRebaseClaimAmountRef = useRef(0n);
  const {
    claim: claimRebaseReward,
    isClaimWritePending: isRebaseClaimWritePending,
    isClaimConfirming: isRebaseClaimConfirming,
    isClaimSuccess: isRebaseClaimSuccess,
    claimReceiptError: rebaseClaimReceiptError,
    rewardDistributor
  } = useClaimRebaseReward();
  const isRebaseClaimPending = isRebaseClaimWritePending || isRebaseClaimConfirming;
  const canClaimRebaseRewards = hasClaimableRebase && Boolean(rewardDistributor);
  const rebaseClaimButtonDisabled = !canClaimRebaseRewards || isRebaseClaimPending;
  const rebaseClaimButtonLabel = isRebaseClaimPending ? "Claiming\u2026" : "Claim";
  const handleRebaseClaim = useCallback(async () => {
    if (!currentLock || !canClaimRebaseRewards || isRebaseClaimPending) {
      return;
    }
    const tokenId = safeBigInt(currentLock.id);
    pendingRebaseClaimAmountRef.current = rebaseClaimable;
    try {
      await claimRebaseReward(tokenId);
    } catch (error) {
      pendingRebaseClaimAmountRef.current = 0n;
      popupRegistry.addPopup(
        {
          type: PopupType.ClaimRewardsError,
          content: {
            type: "error",
            title: "Claim Failed",
            description: errorToString(error) || "Failed to claim rebase rewards.",
            action: "claimRewards"
          }
        },
        `rebase-claim-error-${currentLock.id}-${Date.now()}`
      );
    }
  }, [
    currentLock,
    canClaimRebaseRewards,
    isRebaseClaimPending,
    rebaseClaimable,
    claimRebaseReward
  ]);
  useEffect(() => {
    if (!isRebaseClaimSuccess || !currentLock) {
      return;
    }
    const claimedAmount = pendingRebaseClaimAmountRef.current;
    pendingRebaseClaimAmountRef.current = 0n;
    refetchRebaseClaimables().catch(() => void 0);
    popupRegistry.addPopup(
      {
        type: PopupType.ClaimRewardsSuccess,
        content: {
          type: "success",
          title: "Rebase Claimed",
          description: `Claimed ${formatABXAmount(claimedAmount)} ABX rebase rewards from Lock #${currentLock.id}.`,
          action: "claimRewards"
        }
      },
      `rebase-claim-success-${currentLock.id}-${Date.now()}`
    );
  }, [isRebaseClaimSuccess, currentLock, refetchRebaseClaimables]);
  useEffect(() => {
    if (!rebaseClaimReceiptError || !currentLock) {
      return;
    }
    pendingRebaseClaimAmountRef.current = 0n;
    popupRegistry.addPopup(
      {
        type: PopupType.ClaimRewardsError,
        content: {
          type: "error",
          title: "Claim Failed",
          description: errorToString(rebaseClaimReceiptError) || "Failed to claim rebase rewards.",
          action: "claimRewards"
        }
      },
      `rebase-claim-receipt-error-${currentLock.id}-${Date.now()}`
    );
  }, [rebaseClaimReceiptError, currentLock]);
  return <Flex
    flexDirection="column"
    p={"$spacing16"}
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface3"}
    style={{
      background: `linear-gradient(180deg, ${colors.surface2.variable} 0%, transparent 100%)`
    }}
  >
      <ToggleOptions />

      {activeOption === "Increase" && <Increase />}
      {activeOption === "Extend" && <Extend />}
      {activeOption === "Merge" && <Merge />}
      {activeOption === "Transfer" && <Transfer />}
      {activeOption === "Reset" && <ResetVote />}

      {
    /* Don't show lock time and voting power for Reset, Transfer */
  }
      {activeOption !== "Reset" && activeOption !== "Transfer" && <Flex mt={"$gap24"}>
          <LockTimeAndVotingPower
    votingPower={votingPower}
    lockDuration={lockTime}
  />
        </Flex>}

      {currentLock && <Flex mt={"$gap24"}>
          <Flex
    width="100%"
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface3"}
    backgroundColor={"$surface2Hovered"}
    p={"$spacing16"}
    row
    justifyContent="space-between"
    alignItems="center"
    gap={"$gap16"}
    $md={{
      flexDirection: "column",
      alignItems: "flex-start"
    }}
  >
            <Flex flexDirection="column" gap={"$gap4"}>
              <Text variant="body3" color="$neutral3">
                Rebase
              </Text>
              <Text variant="heading3">{rebaseDisplay}</Text>
            </Flex>
            {canClaimRebaseRewards && <StarBorderButton
    as="button"
    speed="3s"
    disabled={rebaseClaimButtonDisabled}
    onClick={() => {
      handleRebaseClaim().catch(() => void 0);
    }}
  >
                <Flex row alignItems="center" gap="$gap8">
                  {isRebaseClaimPending && <SpinningLoader size={16} />}
                  <Text variant="buttonLabel4" color="inherit">
                    {rebaseClaimButtonLabel}
                  </Text>
                </Flex>
              </StarBorderButton>}
          </Flex>
        </Flex>}

      {
    /* Don't show status cards for Reset, Transfer */
  }
      {activeOption !== "Reset" && activeOption !== "Transfer" && <StatusCards />}

      <ChangeLockAndOptionButton />
    </Flex>;
}
